import type { DatabaseSync } from 'node:sqlite';

/** Shared job rules and the row shape used by both the server and the worker. */

export const MAX_ATTEMPTS = 3;
export const TRANSIENT_ERROR = 'transient failure';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table, with columns named as stored. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  available_at: number;
  created_at: string;
  updated_at: string;
}

/** The public JSON shape of a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

/** Returns the first row of a query, typed as a job row. */
export function one<T>(db: DatabaseSync, sql: string, ...params: (string | number | null)[]): T | undefined {
  return db.prepare(sql).get(...params) as unknown as T | undefined;
}

export interface FieldError {
  field: string;
  message: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export type ParseResult = { ok: true; value: NewJob } | { ok: false; fields: FieldError[] };

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

const isPlainObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

function checkInteger(value: unknown, field: string, min: number, max: number, fallback: number, fields: FieldError[]): number {
  if (value === undefined) return fallback;
  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
    fields.push({ field, message: `must be an integer from ${min} to ${max}` });
    return fallback;
  }
  return value;
}

/** Validates a parsed request body against the job submission rules. */
export function parseNewJob(body: unknown): ParseResult {
  if (!isPlainObject(body)) return { ok: false, fields: [{ field: 'body', message: 'must be a JSON object' }] };
  const fields: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  const { input } = body;
  if (input === undefined) fields.push({ field: 'input', message: 'is required' });
  else if (typeof input !== 'string') fields.push({ field: 'input', message: 'must be a string' });
  else if (input.length < 1 || input.length > 1000) fields.push({ field: 'input', message: 'must be 1 to 1000 characters' });
  else if (input.trim() === '') fields.push({ field: 'input', message: 'must not be blank' });

  const steps = checkInteger(body.steps, 'steps', 1, 20, 5, fields);
  const failAttempts = checkInteger(body.failAttempts, 'failAttempts', 0, 5, 0, fields);

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input: input as string, steps, failAttempts } };
}

