import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';
import { openDatabase, transaction } from './db.ts';
import { one, parseNewJob, toJob, type FieldError, type JobRow } from './jobs.ts';

const db: DatabaseSync = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY_BYTES = 64 * 1024;
const WORKER_STALE_MS = 3000;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const JOB_PATH_RE = /^\/api\/jobs\/([^/]+)$/;

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}

/** Reads the request body as text. Resolves to null when it exceeds the size limit. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      if (tooLarge) return;
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        chunks.length = 0;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function getJobRow(id: string): JobRow | undefined {
  return one<JobRow>(db, 'SELECT * FROM jobs WHERE id = ?', id);
}

async function handleCreateJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];

  const key = req.headers['idempotency-key'];
  if (key !== undefined && !IDEMPOTENCY_KEY_RE.test(key)) {
    fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const mediaType = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  const raw = await readBody(req);
  let value: ReturnType<typeof parseNewJob> | undefined;
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (raw === null) {
    fields.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
  } else {
    let parsed: unknown;
    try {
      parsed = JSON.parse(raw);
      value = parseNewJob(parsed);
      if (!value.ok) fields.push(...value.fields);
    } catch {
      fields.push({ field: 'body', message: 'body is not valid JSON' });
    }
  }

  if (fields.length > 0 || !value || !value.ok) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
    return;
  }
  const input = value.value;
  const payload = JSON.stringify({ input: input.input, steps: input.steps, failAttempts: input.failAttempts });

  // The idempotency check and the insert share one transaction, so concurrent requests with the
  // same key cannot both create a job, and the key survives restarts because it is stored in SQLite.
  const outcome = transaction(db, () => {
    if (key !== undefined) {
      const previous = one<{ payload: string; job_id: string }>(db, 'SELECT payload, job_id FROM idempotency_keys WHERE key = ?', key);
      if (previous) {
        return previous.payload === payload ? { kind: 'replay' as const, id: previous.job_id } : { kind: 'conflict' as const };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, available_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, 0, ?, ?)`,
    ).run(id, input.input, input.steps, input.failAttempts, now, now);
    if (key !== undefined) {
      db.prepare('INSERT INTO idempotency_keys (key, payload, job_id) VALUES (?, ?, ?)').run(key, payload, id);
    }
    return { kind: 'created' as const, id };
  });

  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  const row = getJobRow(outcome.id);
  if (!row) {
    sendError(res, 500, 'internal', 'The job could not be read back.');
    return;
  }
  send(res, outcome.kind === 'created' ? 201 : 200, toJob(row));
}

function handleHealth(res: ServerResponse): void {
  const beat = one<{ beat_at: number }>(db, 'SELECT beat_at FROM worker_heartbeat WHERE name = ?', 'worker');
  const up = beat !== undefined && Date.now() - beat.beat_at <= WORKER_STALE_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function handleRequest(req: IncomingMessage, res: ServerResponse): void {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/') {
    if (method !== 'GET') return sendError(res, 405, 'method_not_allowed', `${method} is not allowed on ${pathname}`);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/health') {
    if (method !== 'GET') return sendError(res, 405, 'method_not_allowed', `${method} is not allowed on ${pathname}`);
    return handleHealth(res);
  }
  if (pathname === '/api/jobs') {
    if (method === 'POST') return void handleCreateJob(req, res).catch((e: unknown) => internalError(res, e));
    if (method !== 'GET') return sendError(res, 405, 'method_not_allowed', `${method} is not allowed on ${pathname}`);
    const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
    return send(res, 200, { jobs: rows.map(toJob) });
  }
  const match = JOB_PATH_RE.exec(pathname);
  if (match) {
    if (method !== 'GET') return sendError(res, 405, 'method_not_allowed', `${method} is not allowed on /api/jobs/:id`);
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No job with that id.');
    }
    const row = getJobRow(id);
    if (!row) return sendError(res, 404, 'not_found', 'No job with that id.');
    return send(res, 200, toJob(row));
  }
  sendError(res, 404, 'not_found', `No route for ${pathname}.`);
}

function internalError(res: ServerResponse, e: unknown): void {
  console.error('request failed:', e);
  if (!res.headersSent) sendError(res, 500, 'internal', 'Internal server error.');
}

const server = createServer((req, res) => {
  try {
    handleRequest(req, res);
  } catch (e) {
    internalError(res, e);
  }
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

