import { setTimeout as sleep } from 'node:timers/promises';
import { setInterval, clearInterval } from 'node:timers';
import type { DatabaseSync } from 'node:sqlite';
import { openDatabase, transaction } from './db.ts';
import { MAX_ATTEMPTS, TRANSIENT_ERROR, one, type JobRow } from './jobs.ts';

const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 1000;

const db: DatabaseSync = openDatabase();
const state = { stopping: false };

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    state.stopping = true;
  });
}

const nowIso = () => new Date().toISOString();

function beat(): void {
  db.prepare(
    'INSERT INTO worker_heartbeat (name, beat_at) VALUES (?, ?) ON CONFLICT (name) DO UPDATE SET beat_at = excluded.beat_at',
  ).run('worker', Date.now());
}

/** Jobs left `running` by a worker that died are queued again; their attempt counts as started. */
function recoverInterruptedJobs(): number {
  const result = db
    .prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = 0, updated_at = ? WHERE status = 'running'")
    .run(nowIso());
  return Number(result.changes);
}

/** Atomically takes the oldest queued job that is due, and marks it running for a new attempt. */
function claimNext(): JobRow | undefined {
  return transaction(db, () => {
    const row = one<JobRow>(db, "SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1", Date.now());
    if (!row) return undefined;
    const attempts = row.attempts + 1;
    db.prepare("UPDATE jobs SET status = 'running', attempts = ?, progress_completed = 0, updated_at = ? WHERE id = ?").run(
      attempts,
      nowIso(),
      row.id,
    );
    return { ...row, status: 'running' as const, attempts };
  });
}

function failAttempt(job: JobRow): void {
  if (job.attempts >= MAX_ATTEMPTS) {
    db.prepare("UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ? WHERE id = ?").run(
      TRANSIENT_ERROR,
      nowIso(),
      job.id,
    );
    console.log(`job ${job.id} failed after ${job.attempts} attempts`);
    return;
  }
  db.prepare("UPDATE jobs SET status = 'queued', available_at = ?, updated_at = ? WHERE id = ?").run(
    Date.now() + RETRY_DELAY_MS,
    nowIso(),
    job.id,
  );
  console.log(`job ${job.id} attempt ${job.attempts} failed; retrying`);
}

function requeue(job: JobRow): void {
  db.prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = 0, updated_at = ? WHERE id = ?").run(nowIso(), job.id);
}

async function processJob(job: JobRow): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    // The simulated dependency fails before any progress is made.
    failAttempt(job);
    return;
  }
  for (let step = 1; step <= job.steps; step++) {
    if (state.stopping) {
      requeue(job);
      return;
    }
    await sleep(STEP_MS);
    db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?').run(step, nowIso(), job.id);
  }
  db.prepare("UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE id = ?").run(
    job.input.toUpperCase(),
    nowIso(),
    job.id,
  );
  console.log(`job ${job.id} completed`);
}

beat();
const heartbeatTimer = setInterval(() => {
  try {
    beat();
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}, HEARTBEAT_MS);

const recovered = recoverInterruptedJobs();
if (recovered > 0) console.log(`requeued ${recovered} interrupted job(s)`);
console.log('worker started');

while (!state.stopping) {
  let job: JobRow | undefined;
  try {
    job = claimNext();
    if (!job) {
      await sleep(IDLE_POLL_MS);
      continue;
    }
    await processJob(job);
  } catch (e) {
    console.error('worker error:', e);
    await sleep(IDLE_POLL_MS);
  }
}

clearInterval(heartbeatTimer);
db.close();
console.log('worker stopped');

